-- ============================================================
-- Sistem Arsip Surat Masuk & Keluar + Disposisi
-- PHP Native + MySQL
-- Import lewat phpMyAdmin atau:  mysql -u root -p < database/arsip_surat.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS arsip_surat CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE arsip_surat;

DROP TABLE IF EXISTS disposisi;
DROP TABLE IF EXISTS surat_keluar;
DROP TABLE IF EXISTS surat_masuk;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS klasifikasi;
DROP TABLE IF EXISTS bagian;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_instansi VARCHAR(150) NOT NULL,
  kode_instansi VARCHAR(30) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  pimpinan VARCHAR(100),
  jabatan_pimpinan VARCHAR(100)
) ENGINE=InnoDB;

CREATE TABLE bagian (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE klasifikasi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(10) NOT NULL UNIQUE,
  nama VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','pimpinan','staf') NOT NULL DEFAULT 'staf',
  bagian_id INT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (bagian_id) REFERENCES bagian(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE surat_masuk (
  id INT AUTO_INCREMENT PRIMARY KEY,
  no_agenda VARCHAR(10) NOT NULL,
  no_surat VARCHAR(100) NOT NULL,
  tgl_surat DATE NOT NULL,
  tgl_terima DATE NOT NULL,
  asal VARCHAR(150) NOT NULL,
  perihal VARCHAR(255) NOT NULL,
  klasifikasi_id INT,
  sifat ENUM('Biasa','Penting','Segera','Rahasia') NOT NULL DEFAULT 'Biasa',
  lampiran VARCHAR(50),
  file VARCHAR(100),
  status ENUM('baru','didisposisi','selesai') NOT NULL DEFAULT 'baru',
  user_id INT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (tgl_terima),
  FOREIGN KEY (klasifikasi_id) REFERENCES klasifikasi(id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE disposisi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  surat_masuk_id INT NOT NULL,
  dari_user_id INT,
  ke_bagian_id INT NOT NULL,
  instruksi VARCHAR(100) NOT NULL,
  catatan TEXT,
  batas_waktu DATE,
  status ENUM('belum','dibaca','selesai') NOT NULL DEFAULT 'belum',
  tanggapan TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (surat_masuk_id) REFERENCES surat_masuk(id) ON DELETE CASCADE,
  FOREIGN KEY (dari_user_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (ke_bagian_id) REFERENCES bagian(id)
) ENGINE=InnoDB;

CREATE TABLE surat_keluar (
  id INT AUTO_INCREMENT PRIMARY KEY,
  no_urut INT NOT NULL,
  nomor_surat VARCHAR(100) NOT NULL UNIQUE,
  tgl_surat DATE NOT NULL,
  tujuan VARCHAR(150) NOT NULL,
  perihal VARCHAR(255) NOT NULL,
  klasifikasi_id INT,
  sifat ENUM('Biasa','Penting','Segera','Rahasia') NOT NULL DEFAULT 'Biasa',
  bagian_id INT,
  file VARCHAR(100),
  user_id INT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (tgl_surat),
  FOREIGN KEY (klasifikasi_id) REFERENCES klasifikasi(id) ON DELETE SET NULL,
  FOREIGN KEY (bagian_id) REFERENCES bagian(id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

