-- Surat masuk contoh (6 bulan terakhir)

-- Nomor agenda diurutkan ulang per tahun berdasarkan tanggal terima
SET @n := 0, @y := 0;
UPDATE surat_masuk SET no_agenda = LPAD(IF(@y = YEAR(tgl_terima), @n := @n + 1, @n := 1 + 0*(@y := YEAR(tgl_terima))), 4, '0') ORDER BY tgl_terima, id;


-- Surat keluar contoh: nomor dibentuk dari urutan per tahun
CREATE TEMPORARY TABLE tmp_sk (tgl DATE, tujuan VARCHAR(150), perihal VARCHAR(255), kid INT, kode VARCHAR(10), sifat VARCHAR(10), bagian INT);
SET @u := 0, @yy := 0;
SELECT urut, CONCAT(LPAD(urut,3,'0'),'/',kode,'/DISKOMINFO/',ELT(MONTH(tgl),'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'),'/',YEAR(tgl)),
       tgl, tujuan, perihal, kid, sifat, bagian, 1
FROM (SELECT t.*, IF(@yy = YEAR(tgl), @u := @u + 1, @u := 1 + 0*(@yy := YEAR(tgl))) urut FROM tmp_sk t ORDER BY tgl) x;
DROP TEMPORARY TABLE tmp_sk;
